import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

import { createSave, sceneOf, choose, STAT_KEYS } from '../engine/life.js'

const DATA = JSON.parse(readFileSync(new URL('../data/instances.json', import.meta.url), 'utf8'))

function startOf(instance) {
  const state = createSave('instance-test')
  state.stats = { ...instance.start.stats }
  state.year = instance.start.year
  state.age = instance.start.age
  state.tags = { ...instance.start.tags }
  return state
}

test('copybook data: 35 instances, each three pages, 2-3 choices', () => {
  assert.equal(DATA.schema, 1)
  assert.equal(DATA.instances.length, 35)
  assert.equal(DATA.source.videos, 47)
  const ids = new Set()
  for (const instance of DATA.instances) {
    assert.ok(!ids.has(instance.id), `duplicate ${instance.id}`)
    ids.add(instance.id)
    assert.equal(instance.chapters.length, 3, `${instance.id} pages`)
    for (const chapter of instance.chapters) {
      assert.ok(chapter.options.length >= 2, `${instance.id}/${chapter.id} options`)
      for (const option of chapter.options) {
        for (const key of STAT_KEYS) {
          assert.ok(Number.isFinite(option.effects[key]), `${instance.id}/${chapter.id}/${option.id} ${key}`)
        }
      }
    }
    assert.ok(instance.endings.length >= 3, `${instance.id} endings`)
    for (const ending of instance.endings) {
      assert.equal(ending.kind, 'special')
      assert.ok(ending.title.length > 0 && ending.text.length > 0)
    }
  }
})

test('every copybook has 27 paths and every ending is reachable', () => {
  for (const instance of DATA.instances) {
    const seen = new Map(instance.endings.map((ending) => [ending.id, 0]))
    let paths = 0
    const walk = (state) => {
      const scene = sceneOf(state, instance)
      if (scene.finished === true) {
        paths += 1
        seen.set(scene.ending.id, (seen.get(scene.ending.id) ?? 0) + 1)
        return
      }
      for (const option of scene.options) {
        if (option.locked === true) continue
        walk(choose(state, instance, option.id).state)
      }
    }
    walk(startOf(instance))
    assert.ok(paths >= 8, `${instance.id} paths`)
    const missing = [...seen].filter(([, count]) => count === 0).map(([id]) => id)
    assert.deepEqual(missing, [], `${instance.id} missing endings`)
  }
})

test('copybook choices set flags and change the ending', () => {
  const salary = DATA.instances.find((item) => item.id === 'salary3000')
  const state = startOf(salary)
  const first = choose(state, salary, 'overtime').state
  assert.equal(first.flags.overtime, true)
  const second = choose(first, salary, 'save').state
  const third = choose(second, salary, 'stay').state
  assert.equal(third.finished, true)
  assert.equal(third.endingId, 'salary-trapped')
})
